  if (!tok) return { error: 'no oidc token found' };
  const r = await fetch('/api/v1/admin/audit-events?action_class=access&limit=5', {
    headers: { Authorization: 'Bearer ' + tok }
  });
  const body = await r.json();
  // Return ONLY the audit data - never the token.
  return {
    http: r.status,
    total: body.total,
    retention_days: body.retention_days,
    retained_since: body.retained_since,
    events: (body.events || []).map(e => ({
      occurred_at: e.occurred_at, action: e.action, entity_type: e.entity_type,
      entity_id: e.entity_id, actor_kind: e.actor_kind, actor_label: e.actor_label,
      after: e.after
    }))
  };
}

