async () => {
  let tok = null;
  for (const store of [sessionStorage, localStorage]) {
    for (let i = 0; i < store.length; i++) {
      const k = store.key(i);
      if (k && k.startsWith('oidc.user:')) {
        try { tok = JSON.parse(store.getItem(k)).access_token; } catch (e) {}
      }
    }
  }
  const H = { Authorization: 'Bearer ' + tok, 'Content-Type': 'application/json' };
  const out = {};
  // CREATE a DISABLED schedule - the dispatcher filters on enabled, so it can never fire.
  const c = await fetch('/api/v1/schedules', { method: 'POST', headers: H, body: JSON.stringify({
    suite_id: '873219fa-2da8-4d82-bba3-a066e173dc63',
    cron: '17 4 * * *', timezone: 'UTC', enabled: false
  })});
  const created = await c.json();
  out.create = { http: c.status, id: created.id, enabled: created.enabled };
  if (c.status < 300 && created.id) {
    const d = await fetch('/api/v1/schedules/' + created.id, { method: 'DELETE', headers: H });
    out.delete = { http: d.status };
  }
  const r = await fetch('/api/v1/admin/audit-events?action_class=config&limit=5', { headers: H });
